import importlib.metadata as md
import sys

REQUIRED = {
    "torch": ">=2.6.0",
    "transformers": ">=4.44.0",
    "peft": ">=0.12.0",
}


def preflight(required: dict[str, str]) -> int:
    """Report EVERY missing/outdated package, then exit non-zero once.

    Returning the full picture in one pass matters: a loop that raises on the
    first missing package makes the user re-run once per dependency.
    """
    problems = []
    for name, spec in required.items():
        try:
            found = md.version(name)
        except md.PackageNotFoundError:
            problems.append(f"missing    {name} (need {spec})")
            continue
        minimum = spec.lstrip('>= ')
        if _older(found, minimum):
            problems.append(f"outdated   {name} {found} < {minimum}")

    if problems:
        print("Environment preflight FAILED:", file=sys.stderr)
        for p in problems:
            print(f"  {p}", file=sys.stderr)
        return 3
    print(f"Environment OK ({len(required)} packages)")
    return 0

