CREATE TABLE IF NOT EXISTS api_keys (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    key_prefix  VARCHAR(64) NOT NULL,
    status        VARCHAR(16) NOT NULL DEFAULT 'active',
    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Composite and ordered to match the read path: equality on the owner, then
-- newest-first. A bare index on the owner would still need a sort.
CREATE INDEX IF NOT EXISTS idx_api_keys_owner_created
    ON api_keys (tenant_id, created_at DESC);

-- Partial index: background workers only scan open rows, so indexing the
-- closed majority is pure write amplification.
CREATE INDEX IF NOT EXISTS idx_api_keys_open
    ON api_keys (created_at)
    WHERE status = 'active';

-- Trigram, because a btree cannot serve '%foo%'.
CREATE INDEX IF NOT EXISTS idx_api_keys_key_prefix_trgm
    ON api_keys USING gin (key_prefix gin_trgm_ops);

COMMIT;

