import math


def lr_at(step: int, *, peak: float, warmup: int, total: int,
          minimum: float) -> float:
    """Linear warmup, then cosine decay to `minimum`.

    Warmup exists because Adam's second-moment estimate is built from very few
    samples at step 0, so its update magnitude is unreliable and a full-size
    first step can wreck the initialisation.
    """
    if step < warmup:
        return peak * (step + 1) / max(warmup, 1)
    progress = min((step - warmup) / max(total - warmup, 1), 1.0)
    return minimum + 0.5 * (peak - minimum) * (
        1.0 + math.cos(math.pi * progress))

