// Context is the FIRST parameter by convention, and the interface takes one
// rather than storing one: a stored context outlives the request that created
// it, and cancellation silently stops working.
package Store

import (
	"context"
	"errors"
)

var ErrNotFound = errors.New("not found")

type Store<T any> interface {
	Get(ctx context.Context, key string) (T, error)
	Put(ctx context.Context, key string, value T) error
}

func GetOr[T any](ctx context.Context, s Store<T>, key string, fallback T) (T, error) {
	v, err := s.Get(ctx, key)
	// errors.Is, never == : a wrapped sentinel compares unequal and the caller
	// would treat a cache miss as a hard failure.
	if errors.Is(err, ErrNotFound) {
		return fallback, nil
	}
	return v, err
}

