  location = var.region

  autoscaling {
    min_node_count = var.min_nodes
    # max must be bounded. An unbounded pool turns a runaway training job
    # into an unbounded bill, and the failure is invisible until the invoice.
    max_node_count = var.max_nodes
  }

  node_config {
    machine_type = "n1-standard-8"
    spot         = true
    # taint + toleration, so general workloads cannot land here and starve
    # the job that actually needs the accelerator.
    taint {
      key    = "dedicated"
      value  = "cpu_pool"
      effect = "NO_SCHEDULE"
    }
  }

  management {
    auto_repair  = true
    auto_upgrade = false
  }
}

